import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__)))); os.chdir(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))+"/out")
from h18 import *
"""Ynmo Flow phase 3 + performance: backlog, sprints, sprint board, burndown, report, team dashboard: cascade delete, ticket links, sorting, labels and due dates, product and Monthly card, bug and report fields, quick create, shortcuts, saved filters, bulk edit, workflow designer (rules, reasons), key repair. Fake test database only."""
import json
R=[]
def ok(n,c): R.append((n,bool(c))); print(('PASS ' if c else 'FAIL ')+n)
with sync_playwright() as pw:
    b=pw.chromium.launch(); ctx=mkctx(b); errs=[]
    A=newpage(ctx,errs); signup(A,'Admin','adm@x.com')
    A.click('#nav button[data-p="flow"]'); A.wait_for_timeout(400)
    def go(v): A.click('.flowitem[data-view="%s"]'%v); A.wait_for_timeout(300)
    def mk(typ,title,**k):
        A.click('#flowcreate'); A.wait_for_timeout(200); A.select_option('#fc-type',typ); A.fill('#fc-title',title)
        if k.get('pts'): A.fill('#fc-pts',str(k['pts']))
        if k.get('sp'): A.select_option('#fc-sp',label=k['sp'])
        A.click('#fc-ok'); A.wait_for_timeout(250)
    go('backlog')
    ok('S1 Backlog and Sprints are real pages now (no Soon tag)', A.locator('.flowitem[data-view="backlog"] .flowsoon').count()==0 and A.locator('.fsprint[data-sp=""]').count()==1)
    A.click('#sp-create'); A.wait_for_timeout(200); A.fill('#sp-name',''); A.click('#sp-save')
    ok('S2 a sprint needs a name', 'name' in A.locator('#sp-err').inner_text().lower())
    A.fill('#sp-name','Sprint 1'); A.fill('#sp-goal','Ship cards'); A.click('#sp-save'); A.wait_for_timeout(300)
    ok('S3 sprint created, planned, with its goal', A.locator('.fsprint[data-sp="s1"]').count()==1 and 'Planned' in A.locator('.fsprint[data-sp="s1"]').inner_text() and 'Ship cards' in A.locator('.fsprint[data-sp="s1"]').inner_text())
    mk('task','Alpha',pts=3); mk('task','Beta',pts=2); mk('bug','Gamma',pts=1)
    ok('S4 new tickets land in the backlog in creation order', A.locator('.fsprint[data-sp=""] .fblrow').count()==3 and 'Alpha' in A.locator('.fsprint[data-sp=""] .fblrow').first.inner_text())
    A.locator('.fsprint[data-sp=""] .fblrow',has_text='Alpha').locator('.fblmove').select_option(label='Sprint 1'); A.wait_for_timeout(300)
    A.locator('.fsprint[data-sp=""] .fblrow',has_text='Beta').locator('.fblmove').select_option(label='Sprint 1'); A.wait_for_timeout(300)
    ok('S5 moving tickets to the sprint with the picker', A.locator('.fsprint[data-sp="s1"] .fblrow').count()==2 and A.locator('.fsprint[data-sp=""] .fblrow').count()==1)
    # drag Gamma into the sprint, before Alpha
    src=A.locator('.fsprint[data-sp=""] .fblrow',has_text='Gamma'); dst=A.locator('.fsprint[data-sp="s1"] .fblrow',has_text='Alpha')
    src.drag_to(dst, target_position={'x':20,'y':2}); A.wait_for_timeout(400)
    names=A.locator('.fsprint[data-sp="s1"] .fblrow .fbltitle').all_inner_texts()
    ok('S6 dragging a ticket into a sprint puts it where it was dropped', names==['Gamma','Alpha','Beta'])
    A.locator('.fsprint[data-sp="s1"] .fblrow',has_text='Gamma').drag_to(A.locator('.fsprint[data-sp="s1"] .fblrow',has_text='Beta'), target_position={'x':20,'y':30}); A.wait_for_timeout(400)
    ok('S7 dragging inside a sprint re-ranks it', A.locator('.fsprint[data-sp="s1"] .fblrow .fbltitle').all_inner_texts()==['Alpha','Beta','Gamma'])
    A.reload(); A.wait_for_timeout(2000); go('backlog')
    ok('S8 the order survives a reload', A.locator('.fsprint[data-sp="s1"] .fblrow .fbltitle').all_inner_texts()==['Alpha','Beta','Gamma'])
    ok('S9 the sprint header counts tickets and points', '3 tickets' in A.locator('.fsprint[data-sp="s1"] .fspcount').inner_text() and '6 pts' in A.locator('.fsprint[data-sp="s1"] .fspcount').inner_text())
    go('sprintboard')
    ok('S10 no sprint running: the sprint board says so and is empty', 'No sprint is running' in A.inner_text('#flowbody') and A.locator('.fcard').count()==0)
    go('sprints'); A.click('.fsprint[data-sp="s1"] button[data-act="start"]'); A.wait_for_timeout(300)
    ok('S11 start sprint: Active tag, burndown chart drawn', 'Active' in A.locator('.fsprint[data-sp="s1"]').inner_text() and A.locator('.fburn').count()==1)
    A.click('#sp-create'); A.wait_for_timeout(200); A.fill('#sp-name','Sprint 2'); A.click('#sp-save'); A.wait_for_timeout(300)
    A.click('.fsprint[data-sp="s2"] button[data-act="start"]'); A.wait_for_timeout(200)
    ok('S12 only one sprint can be active', 'only one sprint' in (A.evaluate("document.getElementById('save').textContent")+A.inner_text('body')).lower())
    go('sprintboard')
    ok('S13 sprint board shows the sprint tickets only', A.locator('.fcard').count()==3)
    A.locator('.fcard',has_text='Alpha').drag_to(A.locator('.fcol[data-st="progress"]')); A.wait_for_timeout(350)
    ok('S14 a card on the sprint board moves like on any board', A.locator('.fcol[data-st="progress"] .fcard',has_text='Alpha').count()==1)
    A.evaluate("""()=>{const s=JSON.parse(localStorage.getItem('fk3'));const k=Object.keys(s.flow_issues).find(x=>s.flow_issues[x].t==='Alpha');const t=s.flow_issues[k];const at=new Date().toISOString();t.st='done';t.up=at;t.hist.push({at:at,by:'Admin',f:'status',a:'In Progress',b:'Done'});localStorage.setItem('fk3',JSON.stringify(s))}""")
    A.reload(); A.wait_for_timeout(2200)
    A.click('#nav button[data-p="flow"]'); A.wait_for_timeout(300); go('issues'); A.click('#flowopen') if A.locator('#flowopen').is_checked() else None; A.select_option('#flowsp','s1'); A.wait_for_timeout(300)
    ok('S15 issue list filters by sprint', A.locator('.flowrow').count()==3)
    A.select_option('#flowsp','@none'); A.wait_for_timeout(300)
    ok('S16 and by "Backlog"', A.locator('.flowrow').count()==0)
    A.select_option('#flowsp',''); A.fill('#flowq','Beta'); A.wait_for_timeout(200); A.locator('.flowrow',has_text='Beta').click(); A.wait_for_timeout(300)
    ok('S17 the ticket window has a Sprint field with the right value', A.locator('#fi-sp option:checked').inner_text()=='Sprint 1')
    A.click('button:text-is("Cancel")') if A.locator('button:text-is("Cancel")').count() else A.keyboard.press('Escape'); A.wait_for_timeout(200)
    go('sprints'); A.click('.fsprint[data-sp="s1"] button[data-act="complete"]'); A.wait_for_timeout(300)
    ok('S18 complete dialog offers backlog and the next sprint', 'Sprint 2' in A.locator('#sp-target').inner_text() and 'backlog' in A.locator('#sp-target').inner_text().lower())
    A.select_option('#sp-target','s2'); A.click('#sp-complete'); A.wait_for_timeout(500)
    t=A.locator('.fsprint[data-sp="s1"]').inner_text()
    ok('S19 completed sprint keeps a report: 1 of 3 finished, 2 moved on', 'Completed' in t and '1 of 3' in t and 'Moved on' in t)
    go('backlog')
    ok('S20 unfinished tickets moved to Sprint 2', A.locator('.fsprint[data-sp="s2"] .fblrow').count()==2)
    A.click('.flowitem[data-view="issues"]'); A.wait_for_timeout(300); A.fill('#flowq','Beta'); A.wait_for_timeout(200); A.locator('.flowrow',has_text='Beta').click(); A.wait_for_timeout(300)
    ok('S21 history says the ticket moved to Sprint 2 by name', 'Sprint 2' in A.inner_text('.flowhist'))
    A.keyboard.press('Escape'); A.wait_for_timeout(200)
    # performance
    go('perf')
    ok('S22 Performance page: tiles, people table, trend, filters', A.locator('.fstat').count()==7 and A.locator('#perftrend .ftcol').count()==8 and A.locator('#perfperiod').count()==1)
    ok('S23 Closed tile counts the finished ticket', A.locator('.fstat[data-stat="Closed"] b').inner_text()=='1')
    A.select_option('#perftype','bug'); A.wait_for_timeout(200)
    ok('S24 type filter narrows the numbers', A.locator('.fstat[data-stat="Closed"] b').inner_text()=='0')
    A.select_option('#perftype',''); A.select_option('#perfperiod','7'); A.wait_for_timeout(200)
    ok('S25 period filter keeps today in', A.locator('.fstat[data-stat="Closed"] b').inner_text()=='1')
    ok('S26 no script errors', not errs)
    if errs: print(errs)
    b.close()
bad=[n for n,c in R if not c]; print('TOTAL',len(R),'PASS',len(R)-len(bad),'FAIL',len(bad)); sys.exit(1 if bad else 0)
